  insert into questions (chapter_id, type, category, source, difficulty, stem_md, options_json, answer_key_md, marks)
  values
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A student places water in a sealed flask. After some time, the water level remains unchanged although evaporation continues. This is because:', '["Evaporation has stopped","Condensation has stopped","Evaporation and condensation occur at equal rates","Water molecules stop moving"]'::jsonb, 'C', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A chemist observes that the concentration of reactants and products remain constant for several hours. Which conclusion is correct?', '["The reaction has stopped","The reaction is irreversible","The system has reached equilibrium","All reactants are consumed"]'::jsonb, 'C', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'In a closed vessel, nitrogen and hydrogen react to form ammonia. Initially, ammonia forms rapidly. After some time, the rate of ammonia formation decreases because:', '["Reverse reaction begins to occur","Catalyst is consumed","Temperature decreases automatically","Pressure becomes zero"]'::jsonb, 'A', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A student claims that no reaction occurs at equilibrium because concentrations remain constant. Why is the statement incorrect?', '["Concentrations are not constant","Only reverse reaction occurs","Both forward and reverse reactions continue at equal rates","Products disappear completely"]'::jsonb, 'C', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'Hydrated copper(II) sulphate crystals are heated until they become white. This colour change indicates:', '["Formation of copper metal","Removal of water molecules","Addition of oxygen","Formation of a new element"]'::jsonb, 'B', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A white sample of anhydrous copper(II) sulphate turns blue after exposure to moist air. This demonstrates:', '["Dehydration","Oxidation","Reversible hydration","Neutralization"]'::jsonb, 'C', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A pink cobalt(II) chloride sample is heated and becomes blue. The heating process favors:', '["Hydration","Dehydration","Condensation","Dissolution"]'::jsonb, 'B', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A sealed container contains liquid water and water vapour at equilibrium. If some vapour is removed, the system will:', '["Remain unchanged","Produce more vapour through evaporation","Stop evaporating","Freeze immediately"]'::jsonb, 'B', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'In an equilibrium system, a student observes millions of molecules reacting every second. This observation supports the concept of:', '["Static equilibrium","Dynamic equilibrium","Irreversible change","Chemical inactivity"]'::jsonb, 'B', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A reaction mixture at equilibrium contains 40% reactants and 60% products. Which statement is correct?', '["Forward rate is greater than reverse rate","Reverse rate is greater than forward rate","Rates of both reactions are equal","Reaction has stopped"]'::jsonb, 'C', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A student increases the temperature of an equilibrium system involving dehydration of hydrated copper sulphate. The equilibrium shifts toward:', '["Hydrated salt","Water formation only","Anhydrous salt formation","No change"]'::jsonb, 'C', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'Why is a closed system necessary for establishing equilibrium?', '["To prevent catalyst loss","To maintain colour changes","To prevent escape of reactants or products","To increase reaction speed only"]'::jsonb, 'C', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A reaction reaches equilibrium after 30 minutes. After another hour, concentrations remain unchanged. This means:', '["No molecules react anymore","Forward and reverse reactions continue equally","Products have disappeared","Temperature is increasing continuously"]'::jsonb, 'B', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A student notices that opening the lid of a bottle containing an equilibrium mixture disturbs the equilibrium because:', '["The system is no longer closed","Temperature becomes zero","Molecules stop moving","Reverse reaction becomes impossible"]'::jsonb, 'A', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A sample of hydrated cobalt chloride is left in a dry environment and gradually turns blue. This happens because:', '["It absorbs water","It loses water molecules","It forms cobalt metal","It reacts with oxygen only"]'::jsonb, 'B', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'Which observation best indicates equilibrium has been reached?', '["Reactants disappear completely","Product concentration becomes zero","Measurable properties remain constant with time","Colour changes continuously"]'::jsonb, 'C', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'In a reversible reaction, the forward reaction rate initially decreases because:', '["Product concentration increases","Catalyst is destroyed","Temperature becomes zero","Molecules stop colliding"]'::jsonb, 'A', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'A student says equilibrium means equal amounts of reactants and products. The correct explanation is:', '["Always true","True only in physical changes","Equilibrium requires equal rates, not necessarily equal amounts","Reactants must be absent"]'::jsonb, 'C', 1),
    (v_chapter, 'mcq', 'scenario', 'bank', 5, 'When water vapour condenses inside a sealed flask, the process represents:', '["Forward reaction only","Reverse process of evaporation","Decomposition reaction","Neutralization"]'::jsonb, 'B', 1),
